import{_ as r,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const s="/assets/%E7%89%A9%E7%90%86%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BA%A7%E5%93%81%E7%AE%A1%E7%90%8611.DH-0EzxK.png",n="/assets/%E7%8B%AC%E6%9C%8D%E6%9C%89%E6%95%88%E7%9A%84.CQ1IMhCU.png",l="/assets/%E7%8B%AC%E6%9C%8D%E4%BD%BF%E7%94%A8vnc.DTSfE25M.png",p="/assets/%E8%BE%93%E5%85%A5%E8%BF%9E%E6%8E%A5%E5%AF%86%E7%A0%8111.8iy66dCH.png",e="/assets/%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95.D3D7Bwxv.png",g="/assets/%E8%BF%9C%E7%A8%8Bip%E8%BF%9E%E6%8E%A5.CuQAbKHx.png",c="/assets/%E7%8B%AC%E6%9C%8D%E5%AF%86%E7%A0%81.B7hYQis7.png",d="/assets/%E7%AD%9B%E9%80%89%E7%8B%AC%E6%9C%8D1.BNq2h0GP.png",E="/assets/shiyongvnc.CPgWFy7t.png",h="/assets/%E5%88%9B%E5%BB%BA%E8%BF%9C%E7%A8%8B%E8%BF%9E%E6%8E%A5.COQb-rvk.png",m="/assets/%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95%E6%88%90%E5%8A%9F11.BzAgzfWR.png",f=JSON.parse('{"title":"登录物理服务器","description":"","frontmatter":{"title":"登录物理服务器"},"headers":[],"relativePath":"dedicatedserver/quickstart/login.md","filePath":"dedicatedserver/quickstart/login.md","lastUpdated":1788259091000}'),_={name:"dedicatedserver/quickstart/login.md"};function u(B,t,A,C,b,S){return a(),i("div",null,[...t[0]||(t[0]=[o('<p>根据购买服务器操作系统类型的不同，可将物理服务器分为 Windows 物理服务器和 Linux 物理服务器。购买并激活服务器后，您可以选择以下方式登录服务器。</p><hr><h3 id="登录-windows-物理服务器" tabindex="-1">登录 Windows 物理服务器 <a class="header-anchor" href="#登录-windows-物理服务器" aria-label="Permalink to &quot;登录 Windows 物理服务器&quot;">​</a></h3><h4 id="方式-1-通过控制台-vnc-登录" tabindex="-1">方式 1：通过控制台 VNC 登录 <a class="header-anchor" href="#方式-1-通过控制台-vnc-登录" aria-label="Permalink to &quot;方式 1：通过控制台 VNC 登录&quot;">​</a></h4><p>VNC 远程控制窗口是连接物理服务器的可视化操作界面，可进行系统操作、文件管理等操作。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击<strong>物理服务器</strong>，进入<strong>我的产品与服务</strong>页面。</p><p><img src="'+s+'" alt="物理服务器产品管理11.png"></p></li><li><p>选择状态为<strong>有效的</strong>物理服务器，单击<strong>产品/服务</strong>名称，进入此服务器的产品详情页面。支持通过地区或状态查找物理服务器</p><p><img src="'+n+'" alt="独服有效的.png"></p></li><li><p>在物理服务器<strong>管理产品</strong>页面，单击<strong>VNC</strong>，进入 VNC 连接面板。</p><p><img src="'+l+'" alt="独服使用vnc.png"></p></li><li><p>在 Windows 系统登录界面，输入服务器密码，完成登录。</p><p><img src="'+p+'" alt="输入连接密码11.png"></p></li></ol><hr><h3 id="方式-2-使用远程桌面登录" tabindex="-1">方式 2：使用远程桌面登录 <a class="header-anchor" href="#方式-2-使用远程桌面登录" aria-label="Permalink to &quot;方式 2：使用远程桌面登录&quot;">​</a></h3><p>本例以 Windows 系统自带的远程桌面连接应用作简要说明。</p><ol><li><p>在本地 Windows 电脑上，按 <code>Win + R</code> 键打开<strong>运行</strong>对话框，输入 <code>mstsc</code>，回车或者单击<strong>确认</strong>打开<strong>远程桌面连接</strong>工具。</p><p><img src="'+e+'" alt="远程登录.png"></p></li><li><p>在<strong>计算机</strong>输入框中，输入 Windows 服务器的公网 IP 地址，如：192.168.1.1。默认的远程桌面端口默认为 3389，如果服务器修改了默认的端口，则需在 IP 加上冒号和本机端口号，如：192.168.1.1:3390。</p><p><img src="'+g+'" alt="远程ip连接.png"></p></li><li><p>单击<strong>连接</strong>。</p></li><li><p>在弹出的窗口中，输入服务器的<strong>管理员账号</strong>（通常是 Administrator）和对应的密码，单击<strong>确定</strong>。</p><p><img src="'+c+'" alt="独服密码.png"></p></li></ol><hr><h3 id="登录-linux-物理服务器" tabindex="-1">登录 Linux 物理服务器 <a class="header-anchor" href="#登录-linux-物理服务器" aria-label="Permalink to &quot;登录 Linux 物理服务器&quot;">​</a></h3><p>登录 Linux 物理服务器包含使用控制台 VNC 功能登录和使用 SSH 远程登录。</p><h4 id="方式-1-通过控制台-vnc-登录-1" tabindex="-1">方式 1：通过控制台 VNC 登录 <a class="header-anchor" href="#方式-1-通过控制台-vnc-登录-1" aria-label="Permalink to &quot;方式 1：通过控制台 VNC 登录&quot;">​</a></h4><p>VNC 远程控制窗口是连接物理服务器的可视化操作界面，可进行系统操作、文件管理等。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击<strong>物理服务器</strong>，进入<strong>我的产品与服务</strong>页面。</p><p><img src="'+s+'" alt="物理服务器产品管理11.png"></p></li><li><p>在<strong>我的产品与服务</strong>页面，可以通过地区或状态查找物理服务器。</p><p><img src="'+d+'" alt="筛选独服1.png"></p></li><li><p>选择状态为<strong>有效的</strong>物理服务器，单击<strong>产品/服务</strong>名称，进入此服务器的<strong>管理产品</strong>页面。</p><p><img src="'+n+'" alt="独服有效的.png"></p></li><li><p>单击<strong>VNC</strong>，进入 VNC 连接面板。详细的连接步骤可参考上述登录 Windows 物理服务器 - 通过控制台 VNC 登录。</p><p><img src="'+E+'" alt="shiyongvnc.png"></p></li></ol><h4 id="方式-2-使用-ssh-客户端远程登录" tabindex="-1">方式 2：使用 SSH 客户端远程登录 <a class="header-anchor" href="#方式-2-使用-ssh-客户端远程登录" aria-label="Permalink to &quot;方式 2：使用 SSH 客户端远程登录&quot;">​</a></h4><p>通过 SSH 远程连接服务器是指是指使用 SSH 工具，在本地设备上通过网络远程访问服务器，登录系统进行命令行操作的过程。</p><h5 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h5><p>本地设备已安装 SSH 客户端：</p><ul><li>Windows 可使用 PuTTY、Xshell；</li><li>Mac/Linux 可用自带终端。</li></ul><h5 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h5><ol><li><p>打开本地 SSH 客户端工具。</p><p><img src="'+h+'" alt="创建远程连接.png"></p></li><li><p>在连接配置中填写如下信息。</p><ul><li>名称：服务器主机名。</li><li>主机地址：服务器主 IP；</li><li>端口：默认 SSH 端口为 22；</li><li>方法：支持密码、公钥和Keyboard Interactive方式，选择其中一种方式；</li><li>用户名：root（对应操作系统用户名）。</li><li>密码：服务器连接密码。</li></ul><blockquote><p><strong>说明</strong></p><p>可在产品信息邮件中查找对应密码。产品信息邮件会在产品购买开通后由 RakSmart 发送给用户。</p></blockquote></li><li><p>单击<strong>确定</strong>，远程连接服务器成功如下图所示。</p><p><img src="'+m+'" alt="远程登录成功11.png"></p></li></ol>',23)])])}const q=r(_,[["render",u]]);export{f as __pageData,q as default};
